    const boot = () => { try {
        window.stop();
        const parsed = new DOMParser().parseFromString(payload.html, 'text/html');
        if (parsed.querySelector('script')) throw Error('Unexpected script in HTML template.');
        const root = document.importNode(parsed.documentElement, true);
        while (document.firstChild) document.removeChild(document.firstChild);
        document.append(document.implementation.createDocumentType('html', '', ''));
        document.append(root);
        window.__EON_WASM_BINARY__ = Uint8Array.from(atob(payload.wasm), c => c.charCodeAt(0));
        const gradient = '<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512"><defs><radialGradient id="g"><stop offset="0" stop-color="white" stop-opacity="0"/><stop offset="1" stop-color="black" stop-opacity=".7"/></radialGradient></defs><circle cx="256" cy="256" r="256" fill="url(#g)"/></svg>';
        const empty = 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"/>');
        const fetchSkin = typeof GM_xmlhttpRequest !== 'function' ? null : url => new Promise((resolve, reject) => {
            const target = new URL(url), maxBytes = 8 * 1024 * 1024;
            if (!/^https?:$/.test(target.protocol) || target.username || target.password) {
                reject(new Error('Skin must be a public HTTP(S) image URL.')); return;
            }
            let request;
            const fail = () => reject(new Error('Could not download the skin image.'));
            request = GM_xmlhttpRequest({method:'GET', url:target.href, responseType:'blob', anonymous:true, timeout:15000,
                onload: response => {
                    const blob = response.response;
                    if (response.status < 200 || response.status >= 300 || !blob || !blob.size || blob.size > maxBytes ||
                        !/^image\//i.test(blob.type)) { fail(); return; }
                    resolve(blob);
                },
                onprogress: progress => { if (progress.loaded > maxBytes || progress.total > maxBytes) { request?.abort(); fail(); } },
                onerror: fail, ontimeout: fail, onabort: fail
            });
        });
        window.EonAssets = {
            protocolLoader: () => payload.scripts.find(item => item.name === 'wasmLoader.js')?.source,
            cursor: name => payload.cursors[name] || empty,
            cursorInfo: name => payload.cursorInfo[name] || null,
            cursorCss: name => payload.cursors[name] ? 'url("' + payload.cursors[name] + '"), auto' : 'auto',
            gradient: 'data:image/svg+xml,' + encodeURIComponent(gradient),
            fetchSkin
        };
        for (const item of payload.scripts) {
            new window.Function(item.source + '\n//# sourceURL=eon-senpa://' + item.name).call(window);
        }
    } catch (error) {
        const notice = document.createElement('div');
        notice.style.cssText = 'position:fixed;inset:20px;z-index:999999;padding:30px;background:#151d28;color:white;white-space:pre-wrap';
        notice.textContent = 'Eon could not start: ' + error.message + '\nDisable this userscript and reload to return to Senpa.';
        (document.body || document.documentElement).append(notice);
    }
    window.addEventListener('pagehide', () => window.SenpaAccount?.dispose());
    };
    boot();
